1	import { describe, expect, it } from 'vitest';
2	import {
3		ANGULAR_SUPER_PRODUCTIVITY_APP,
4		ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS,
5		ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_CHAIN,
6		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_CONSOLE_ERRORS,
7		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_FAILED_REQUESTS,
8		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_HOST_TAG_CORRECTION,
9		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_JOURNEY,
10		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_KEY_ORDER_CORRECTION,
11		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_LANE_SEAMS,
12		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MEASURED_STYLE_DIFFERENCES,
13		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_REGRESSION,
14		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE,
15		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE,
16		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SEAMS,
17		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER,
18		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SETTINGS,
19		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES,
20		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE,
21		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TIME_TRACKING_REANCHOR,
22		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_DEGRADATION_CAUSE,
23		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_PROBE,
24	} from '../../core/src/receipts/witness-angular-super-productivity.ts';
25	import {
26		angularSuperProductivityWitnessSpec,
27		assertWitnessAdHocStyleProbes,
28	} from '../src/witness/real-app-run.ts';
29	
30	const spec = angularSuperProductivityWitnessSpec();
31	const journey = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_JOURNEY;
32	
33	describe('the Super Productivity journey wiring', () => {
34		it('is the Angular vertical the receipt schema names, on the roots it binds', () => {
35			expect(spec.app).toBe(ANGULAR_SUPER_PRODUCTIVITY_APP);
36			expect(spec.framework).toBe('angular');
37			const bound = Object.fromEntries(
38				ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS.map((receipt) => [
39					receipt.lane,
40					receipt.canonicalRoot,
41				]),
42			);
43			// The lane roots the spec serves must END with the canonical output root
44			// the schema pins for that lane; serving a sibling would be serving one
45			// build rather than the lane the bound record describes.
46			expect(spec.sources.baseline.endsWith(bound.baseline!)).toBe(true);
47			expect(spec.sources.migrated.endsWith(bound.migrated!)).toBe(true);
48		});
49	
50		it('binds the migrated build record by the sha256 of its exact bytes', () => {
51			const migrated = ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS.find(
52				(receipt) => receipt.lane === 'migrated',
53			);
54			expect(spec.canonicalBinding).toBe('file-sha256');
55			expect(spec.canonicalReceipt).toBe(migrated!.path);
56			expect(spec.canonicalDigest).toBe(migrated!.sha256);
57			// The record it binds has to be the end of the migrated lane's supersession
58			// chain, or the proof would be served from a build the chain says was
59			// contradicted.
60			expect(spec.canonicalReceipt).toBe(
61				ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_CHAIN.at(-1)!.record,
62			);
63			expect(ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_CHAIN.at(-1)!.contradictedBy).toBeNull();
64		});
65	
66		it('deep-links the declared work-view route rather than the bare document', () => {
67			// Measured: the bare document records its navigation as `#/`, which the
68			// router resolves through its `**` route. The schema refuses a recorded
69			// route the application does not declare, and `/` is not one of the nine.
70			expect(spec.initialRoute).toBe(journey.initialRoute);
71			expect(journey.initialRoute).toBe('/#/work-view');
72			expect(WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE.known).toContain('/work-view');
73			expect(journey.initialRoute.startsWith(`/${WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE.prefix}`)).toBe(
74				true,
75			);
76			// After the deep-linked load: the leg-(e) reload (two — the document commit
77			// and the router's own hash settle each record one) and the two leg-(d)
78			// hash navigations (into `#/project-settings` and back to `#/work-view`).
79			// The leg-(d) project switch records none. Four, exactly.
80			expect(journey.navigations).toBe(4);
81		});
82	
83		it('measures against a stated viewport, because it claims scroll absence', () => {
84			expect(spec.viewport).toEqual({ width: 1280, height: 900 });
85			expect(spec.viewport).toEqual(journey.viewport);
86		});
87	
88		it('declares the exact probe list the schema checks, in the schema order', () => {
89			expect(spec.renderedStyleProbes).toBe(WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES);
90			// The typeface reading is anchored on a probe that is actually measured,
91			// and on one the two lanes agree about — the reasoning is beside the
92			// constant, and this is the half of it a test can hold.
93			const labels = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES.map((probe) => probe.label);
94			expect(labels).toContain(WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_PROBE);
95			expect(
96				WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MEASURED_STYLE_DIFFERENCES.map(
97					(difference) => difference.label,
98				),
99			).not.toContain(WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_PROBE);
100			// Every measured difference names a probe that exists, and actually differs.
101			for (const difference of WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MEASURED_STYLE_DIFFERENCES) {
102				expect(labels).toContain(difference.label);
