6680	async function zeroServiceWorkerCheckpoint(
6681		lifecycle: JourneyLifecycle,
6682		phase: 'before-interactions' | 'after-interactions' | 'after-online-reload',
6683	): Promise<{
6684		phase: typeof phase;
6685		state: 'timeout';
6686		registrations: 0;
6687		controller: null;
6688		cacheNames: [];
6689		workerEvents: [];
6690	}> {
6691		const telemetry = await lifecycle.serviceWorkerTelemetry(250);
6692		if (
6693			telemetry.state !== 'timeout' ||
6694			telemetry.registration.scriptPath !== null ||
6695			telemetry.registration.scope !== null ||
6696			telemetry.registration.installing !== null ||
6697			telemetry.registration.waiting !== null ||
6698			telemetry.registration.active !== null ||
6699			telemetry.controller !== null ||
6700			telemetry.cacheNames.length !== 0 ||
6701			telemetry.cacheEntries.length !== 0 ||
6702			telemetry.workerEvents.length !== 0
6703		)
6704			// The refusal carries what was observed. An assertion that only says it
6705			// failed makes the next reader guess which of nine facts moved.
6706			throw new Error(
6707				`zero-service-worker policy assertion failed: ${phase} ${canonicalize(telemetry)}`,
6708			);
6709		return {
6710			phase,
6711			state: 'timeout',
6712			registrations: 0,
6713			controller: null,
6714			cacheNames: [],
6715			workerEvents: [],
6716		};
6717	}
6718	
6719	/**
6720	 * The checkpoint for a registration the browser refuses.
6721	 *
6722	 * Every settled fact the zero-worker checkpoint asserts is asserted here too —
6723	 * nothing ready, nothing registered, nothing installing, waiting or active,
6724	 * nothing controlling the page and no CacheStorage entry. What is NOT asserted
6725	 * away is the observer trace: a rejected registration still leaves a record of
6726	 * the attempt, and every event in it is required to name the script the
6727	 * application asked for and the scope it asked for it at. An event about any
6728	 * other script, or a registration that got as far as a version worth running,
6729	 * fails the checkpoint.
6730	 */
6731	async function refusedServiceWorkerCheckpoint(
6732		lifecycle: JourneyLifecycle,
6733		phase: 'before-interactions' | 'after-interactions' | 'after-online-reload',
6734		attempt: { script: string; scopePath: string },
6735	): Promise<
6736		NonNullable<JourneyEvidence['refusedServiceWorker']>['checkpoints'][number]
6737	> {
6738		const telemetry = await lifecycle.serviceWorkerTelemetry(250);
6739		const attemptEvents = telemetry.workerEvents;
6740		const named = attemptEvents.every((event) =>
6741			event.kind === 'registration'
6742				? event.scopePath === attempt.scopePath
6743				: event.kind === 'version'
6744					? event.scriptPath === attempt.script && event.runningStatus === 'stopped'
6745					: false,
6746		);
6747		if (
6748			telemetry.state !== 'timeout' ||
6749			telemetry.registration.scriptPath !== null ||
6750			telemetry.registration.scope !== null ||
6751			telemetry.registration.installing !== null ||
6752			telemetry.registration.waiting !== null ||
6753			telemetry.registration.active !== null ||
6754			telemetry.controller !== null ||
6755			telemetry.cacheNames.length !== 0 ||
6756			telemetry.cacheEntries.length !== 0 ||
6757			attemptEvents.length === 0 ||
6758			!named
6759		)
6760			throw new Error(
6761				`refused-service-worker checkpoint failed: ${phase} ${canonicalize(telemetry)}`,
6762			);
6763		return {
6764			phase,
6765			state: 'timeout',
6766			registrations: 0,
6767			controller: null,
6768			cacheNames: [],
6769			attemptEvents,
6770		};
6771	}
6772	
6773	/**
6774	 * The checkpoint for a worker that is genuinely running, which is the inverse of
6775	 * the two above: nothing is asserted to be empty, and quite a lot is asserted to
6776	 * be present.
6777	 *
6778	 * The reading has to have SETTLED — `ready` rather than the timeout every
6779	 * absence shape records — and the registration has to name the script the
6780	 * application asked for, at a scope, with an active version. What is
6781	 * deliberately not asserted is which version, which caches, or whether the page
6782	 * is controlled at this particular phase: those are measurements that differ
6783	 * legitimately between the first checkpoint and the last, and an application's
6784	 * own receipt schema is where they are pinned and compared across lanes.
6785	 */
6786	export async function realServiceWorkerCheckpoint(
6787		lifecycle: { serviceWorkerTelemetry(timeoutMs: number): Promise<ServiceWorkerTelemetry> },
6788		phase: (typeof WITNESS_REAL_SERVICE_WORKER_PHASES)[number],
6789		script: string,
6790		timeoutMs = 10_000,
6791	): Promise<WitnessRealServiceWorkerCheckpoint> {
6792		const telemetry = await lifecycle.serviceWorkerTelemetry(timeoutMs);
6793		if (
6794			telemetry.state !== 'ready' ||
6795			telemetry.registration.scriptPath === null ||
6796			!telemetry.registration.scriptPath.endsWith(script) ||
6797			telemetry.registration.scope === null ||
