export async function executeAngularSuperProductivityWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	const app = apps.find((candidate) => candidate.app === ANGULAR_SUPER_PRODUCTIVITY_APP);
	if (app === undefined)
		throw new Error('Super Productivity Witness specification is absent');
	return await executeRun(app, options.lane, options.pass, options);
}

/**
 * The jira-clone Witness specification, reachable so its declared inventories,
 * probes and seams can be checked against the receipt schema that enforces them
 * without launching a browser.
 */
export function angularJiraCloneWitnessSpec(): AppSpec {
	const app = apps.find((candidate) => candidate.app === 'angular-jira-clone');
	if (app === undefined) throw new Error('jira-clone Witness specification is absent');
	return app;
}

/**
 * jira-clone ships no service worker in either lane and never calls
 * `register()`, so the run is executed under the zero-worker policy: the
 * browser context still allows registration, and the journey is required to
 * observe nothing registered, controlling, cached or requested at each of its
 * three checkpoints.
 */
export async function executeAngularJiraCloneWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	return await executeRun(angularJiraCloneWitnessSpec(), options.lane, options.pass, {
		...options,
		serviceWorkerPolicy: 'zero',
	});
}

/**
 * The killedbygoogle v3 Witness specification, reachable so its declared
 * inventories, probes and lane bindings can be checked against the receipt
 * schema that enforces them without launching a browser.
 */
export function nextKilledbygoogleV3WitnessSpec(): AppSpec {
	const app = apps.find((candidate) => candidate.app === NEXT_KILLEDBYGOOGLE_V3_APP);
	if (app === undefined) throw new Error('KilledByGoogle v3 Witness specification is absent');
	return app;
}

/**
 * Neither lane ships a service worker and the application never calls
 * `register()`, so the run is executed under the zero-worker policy: the browser
 * context still allows registration, and the journey is required to observe
 * nothing registered, controlling, cached or requested at each of its three
 * checkpoints.
 */
export async function executeNextKilledbygoogleV3WitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	return await executeRun(nextKilledbygoogleV3WitnessSpec(), options.lane, options.pass, {
		...options,
		serviceWorkerPolicy: 'zero',
	});
}

async function zeroServiceWorkerCheckpoint(
	lifecycle: JourneyLifecycle,
	phase: 'before-interactions' | 'after-interactions' | 'after-online-reload',
): Promise<{
	phase: typeof phase;
	state: 'timeout';
	registrations: 0;
	controller: null;
	cacheNames: [];
	workerEvents: [];
}> {
	const telemetry = await lifecycle.serviceWorkerTelemetry(250);
	if (
		telemetry.state !== 'timeout' ||
		telemetry.registration.scriptPath !== null ||
		telemetry.registration.scope !== null ||
		telemetry.registration.installing !== null ||
		telemetry.registration.waiting !== null ||
		telemetry.registration.active !== null ||
		telemetry.controller !== null ||
		telemetry.cacheNames.length !== 0 ||
		telemetry.cacheEntries.length !== 0 ||
		telemetry.workerEvents.length !== 0
	)
		// The refusal carries what was observed. An assertion that only says it
		// failed makes the next reader guess which of nine facts moved.
		throw new Error(
			`zero-service-worker policy assertion failed: ${phase} ${canonicalize(telemetry)}`,
		);
	return {
		phase,
		state: 'timeout',
		registrations: 0,
		controller: null,
		cacheNames: [],
		workerEvents: [],
	};
}

/**
 * The checkpoint for a registration the browser refuses.
 *
 * Every settled fact the zero-worker checkpoint asserts is asserted here too —
 * nothing ready, nothing registered, nothing installing, waiting or active,
 * nothing controlling the page and no CacheStorage entry. What is NOT asserted
 * away is the observer trace: a rejected registration still leaves a record of
 * the attempt, and every event in it is required to name the script the
 * application asked for and the scope it asked for it at. An event about any
 * other script, or a registration that got as far as a version worth running,
 * fails the checkpoint.
 */
async function refusedServiceWorkerCheckpoint(
	lifecycle: JourneyLifecycle,
	phase: 'before-interactions' | 'after-interactions' | 'after-online-reload',
	attempt: { script: string; scopePath: string },
): Promise<
	NonNullable<JourneyEvidence['refusedServiceWorker']>['checkpoints'][number]
> {
	const telemetry = await lifecycle.serviceWorkerTelemetry(250);
	const attemptEvents = telemetry.workerEvents;
	const named = attemptEvents.every((event) =>
		event.kind === 'registration'
			? event.scopePath === attempt.scopePath
			: event.kind === 'version'
				? event.scriptPath === attempt.script && event.runningStatus === 'stopped'
				: false,
	);
	if (
		telemetry.state !== 'timeout' ||
		telemetry.registration.scriptPath !== null ||
		telemetry.registration.scope !== null ||
		telemetry.registration.installing !== null ||
		telemetry.registration.waiting !== null ||
		telemetry.registration.active !== null ||
		telemetry.controller !== null ||
		telemetry.cacheNames.length !== 0 ||
		telemetry.cacheEntries.length !== 0 ||
		attemptEvents.length === 0 ||
		!named
	)
		throw new Error(
			`refused-service-worker checkpoint failed: ${phase} ${canonicalize(telemetry)}`,
		);
	return {
		phase,
		state: 'timeout',
		registrations: 0,
		controller: null,
		cacheNames: [],
		attemptEvents,
	};
}

/**
 * The checkpoint for a worker that is genuinely running, which is the inverse of
 * the two above: nothing is asserted to be empty, and quite a lot is asserted to
 * be present.
 *
 * The reading has to have SETTLED — `ready` rather than the timeout every
 * absence shape records — and the registration has to name the script the
 * application asked for, at a scope, with an active version. What is
 * deliberately not asserted is which version, which caches, or whether the page
 * is controlled at this particular phase: those are measurements that differ
 * legitimately between the first checkpoint and the last, and an application's
 * own receipt schema is where they are pinned and compared across lanes.
 */
export async function realServiceWorkerCheckpoint(
	lifecycle: { serviceWorkerTelemetry(timeoutMs: number): Promise<ServiceWorkerTelemetry> },
	phase: (typeof WITNESS_REAL_SERVICE_WORKER_PHASES)[number],
	script: string,
	timeoutMs = 10_000,
): Promise<WitnessRealServiceWorkerCheckpoint> {
	const telemetry = await lifecycle.serviceWorkerTelemetry(timeoutMs);
	if (
		telemetry.state !== 'ready' ||
		telemetry.registration.scriptPath === null ||
		!telemetry.registration.scriptPath.endsWith(script) ||
		telemetry.registration.scope === null ||
		telemetry.registration.active === null ||
		telemetry.workerEvents.length === 0
	)
		// The refusal carries the reading, so the next reader does not have to
		// guess which of six facts moved.
		throw new Error(
			`real-service-worker checkpoint failed: ${phase} ${canonicalize(telemetry)}`,
		);
	return { phase, telemetry: { ...telemetry, state: 'ready' } };
}

