5291		 * receipt schema refuses as a recorded navigation. Asking for the declared
5292		 * route is what makes the recorded navigation a declared one.
5293		 */
5294		initialRoute: SUPER_PRODUCTIVITY_JOURNEY.initialRoute,
5295		viewport: SUPER_PRODUCTIVITY_JOURNEY.viewport,
5296		consoleErrorInventory: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_CONSOLE_ERRORS,
5297		failedRequestInventory: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_FAILED_REQUESTS,
5298		mockedNonLoopbackSeams: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_LANE_SEAMS,
5299		renderedStyleProbes: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES,
5300		indexedDb: 'read-keys',
5301		/**
5302		 * The one seam either lane reaches for: the Roboto stylesheet the
5303		 * application's own `index.html` links. It is answered in-context with an
5304		 * empty body, so nothing leaves the machine and the request is still written
5305		 * down — and the glyphs never arrive, which is the typeface degradation the
5306		 * journey measures rather than hides.
5307		 */
5308		transport: async () => ({
5309			action: 'fulfill',
5310			status: 200,
5311			contentType: 'text/css',
5312			body: Buffer.alloc(0),
5313		}),
5314		journey: async (context, page, _transportEvidence, lifecycle) => {
5315			if (lifecycle.expectedServiceWorker !== null)
5316				throw new Error('Super Productivity journey received a service-worker expectation');
5317			const script = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER.script;
5318			const checkpoints: WitnessRealServiceWorkerCheckpoint[] = [
5319				await realServiceWorkerCheckpoint(lifecycle, 'before-interactions', script),
5320			];
5321			const measuredRoutes: WitnessMeasuredScrollAbsence['routes'] = [];
5322			/**
5323			 * Taken at every stage. The application pins its drawer container to the
5324			 * viewport and scrolls its own inner panels, so a stage that started
5325			 * overflowing fails here rather than passing silently unexercised.
5326			 */
5327			const measure = async (stage: string): Promise<void> => {
5328				const extents = await lifecycle.viewportScroll();
5329				if (
5330					extents.clientHeight !== SUPER_PRODUCTIVITY_JOURNEY.viewport.height ||
5331					extents.scrollHeight > extents.clientHeight ||
5332					extents.scrollY !== 0
5333				)
5334					throw new Error(
5335						`Super Productivity stage overflows the viewport the receipt says it does not: ${stage} ${canonicalize(extents)}`,
5336					);
5337				measuredRoutes.push({
5338					route: stage,
5339					scrollHeight: extents.scrollHeight,
5340					clientHeight: extents.clientHeight,
5341				});
5342			};
5343			/** The application's own store, read for its keys and never its values. */
5344			const storeKeys = async (): Promise<string[]> =>
5345				witnessIndexedDbStringKeys(
5346					await lifecycle.indexedDbKeys(),
5347					WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.databaseName,
5348					WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.storeName,
5349				);
5350			const localKeys = async (): Promise<string[]> => {
5351				const keys = await lifecycle.browserStorageKeys();
5352				if (keys.sessionStorage.length !== 0)
5353					throw new Error(
5354						`Super Productivity wrote session storage the receipt says it does not: ${canonicalize(keys.sessionStorage)}`,
5355					);
5356				return [...keys.localStorage].sort();
5357			};
5358			/** The rendered task titles in document order, for legs (b) and (e). */
5359			const readOrder = async (): Promise<string[]> =>
5360				(await lifecycle.groupedText(SUPER_PRODUCTIVITY_JOURNEY.taskTitleProbe)).map(
5361					(group) => group.name,
5362				);
5363			/** The single icon the header's own global play button renders, for leg (c). */
5364			const readHeaderIcon = async (): Promise<string> => {
5365				const icons = (
5366					await lifecycle.groupedText(SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconProbe)
5367				).flatMap((group) => group.items);
5368				if (icons.length !== 1)
5369					throw new Error(
5370						`Super Productivity header play button rendered ${icons.length} icons, not one`,
5371					);
5372				return icons[0]!;
5373			};
5374			await page.trackEvents('click', 'input', 'keydown');
5375	
5376			// The application as it boots: the work view's own host tag — `work-view`,
5377			// not the component's file name — its two task lists, and no task in
5378			// either of them. Nothing has been seeded; this application starts empty.
5379			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.hostTag, 1);
5380			await context.expect.page.count(
5381				page,
5382				SUPER_PRODUCTIVITY_JOURNEY.taskList,
5383				SUPER_PRODUCTIVITY_JOURNEY.taskLists,
5384			);
5385			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 0);
5386			const renderedStyles = await lifecycle.renderedStyles();
5387			const keysBeforeJourney = await storeKeys();
5388			const localStorageKeysBeforeJourney = await localKeys();
5389			await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (before the create)`);
5390	
5391			// (a) The create. The add-task bar is configured `[isAddToBacklog]="false"`
5392			// in the work view's own template, so a title committed with Enter lands in
5393			// today's list rather than in the backlog — which is what the count below
5394			// is actually testing, and why it is asserted on `task-list task` rather
5395			// than on `task` anywhere in the document.
5396			await page.type(
5397				SUPER_PRODUCTIVITY_JOURNEY.addTaskInput,
5398				SUPER_PRODUCTIVITY_JOURNEY.taskTitleText,
5399				{ redact: false },
5400			);
5401			await page.press(SUPER_PRODUCTIVITY_JOURNEY.addTaskInput, 'Enter');
5402			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 1);
5403			await context.expect.page.text(
5404				page,
5405				SUPER_PRODUCTIVITY_JOURNEY.taskTitle,
5406				SUPER_PRODUCTIVITY_JOURNEY.taskTitleText,
5407			);
5408			await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after the create)`);
5409	
5410			// A second task, so leg (b) has a list to reorder. It lands below the
5411			// first, and that first-created-on-top order is where leg (b) begins.
5412			await page.type(
5413				SUPER_PRODUCTIVITY_JOURNEY.addTaskInput,
5414				SUPER_PRODUCTIVITY_JOURNEY.secondTaskTitleText,
5415				{ redact: false },
5416			);
5417			await page.press(SUPER_PRODUCTIVITY_JOURNEY.addTaskInput, 'Enter');
5418			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 2);
5419			const renderedOrderBefore = await readOrder();
5420			if (
5421				canonicalize(renderedOrderBefore) !==
5422				canonicalize(SUPER_PRODUCTIVITY_JOURNEY.reorder.renderedOrderBefore)
5423			)
5424				throw new Error(
5425					`Super Productivity created list differs from the pinned before-order: ${canonicalize(renderedOrderBefore)}`,
5426				);
5427			await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after the second create)`);
5428	
5429			// (c) Time tracking, anchored on the header's own global play button. The
5430			// per-task start button is hover-gated and the accrued value is sub-minute
5431			// (both recorded as non-claims on the re-anchor constant), so the anchor is
5432			// the header button icon: it flips play_arrow to pause on start with one
5433			// task made current, and back to play_arrow on stop with it cleared. A
5434			// settled anchor read off the DOM, never a timing.
5435			const iconBeforeStart = await readHeaderIcon();
5436			if (iconBeforeStart !== SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconBeforeStart)
5437				throw new Error(`Super Productivity header icon before start differs: ${iconBeforeStart}`);
5438			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.timeTracking.currentTask, 0);
5439			await page.click(SUPER_PRODUCTIVITY_JOURNEY.timeTracking.playButton);
5440			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.timeTracking.currentTask, 1);
5441			const iconAfterStart = await readHeaderIcon();
5442			if (iconAfterStart !== SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconAfterStart)
5443				throw new Error(`Super Productivity header icon after start differs: ${iconAfterStart}`);
5444			await page.click(SUPER_PRODUCTIVITY_JOURNEY.timeTracking.playButton);
5445			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.timeTracking.currentTask, 0);
5446			const iconAfterStop = await readHeaderIcon();
5447			if (iconAfterStop !== SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconAfterStop)
5448				throw new Error(`Super Productivity header icon after stop differs: ${iconAfterStop}`);
