5457				{ steps: SUPER_PRODUCTIVITY_JOURNEY.reorder.steps },
5458			);
5459			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 2);
5460			const renderedOrderAfter = await readOrder();
5461			if (
5462				canonicalize(renderedOrderAfter) !==
5463				canonicalize(SUPER_PRODUCTIVITY_JOURNEY.reorder.renderedOrderAfter)
5464			)
