5470	
5471			// (e) A real document reload. There is no backend: the two tasks and the
5472			// order the drag settled them into are in the application's own IndexedDB
5473			// store, and what comes back — read off the re-rendered list — is the store
5474			// list, which is what makes it the store's own agreement with the drag.
5475			await page.reload();
5476			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 2);
5477			const storeOrderAfter = await readOrder();
5478			if (canonicalize(storeOrderAfter) !== canonicalize(renderedOrderAfter))
5479				throw new Error(
5480					`Super Productivity store order after reload differs from the rendered reorder: ${canonicalize(storeOrderAfter)}`,
5481				);
5482			const keysAfterJourney = await storeKeys();
5483			const localStorageKeysAfterJourney = await localKeys();
5484			await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after the online reload)`);
5485			checkpoints.push(
5486				await realServiceWorkerCheckpoint(lifecycle, 'after-online-reload', script),
5487			);
5488			// The census is the persistence claim. Committing one task adds the four
5489			// state documents the application writes for its default project and takes
5490			// nothing away, and the reload changes neither list — which is what makes
5491			// the re-rendered title a read out of the store rather than a survival of
5492			// the page.
5493			if (
5494				canonicalize(keysBeforeJourney) !==
5495					canonicalize(SUPER_PRODUCTIVITY_JOURNEY.keysBeforeJourney) ||
5496				canonicalize(keysAfterJourney) !==
5497					canonicalize(SUPER_PRODUCTIVITY_JOURNEY.keysAfterJourney) ||
5498				canonicalize(localStorageKeysBeforeJourney) !==
5499					canonicalize(SUPER_PRODUCTIVITY_JOURNEY.localStorageKeysBeforeJourney) ||
5500				canonicalize(localStorageKeysAfterJourney) !==
5501					canonicalize(SUPER_PRODUCTIVITY_JOURNEY.localStorageKeysAfterJourney)
5502			)
5503				throw new Error(
5504					`Super Productivity key census differs from the pinned measurement: ${canonicalize({
5505						keysBeforeJourney,
5506						keysAfterJourney,
5507						localStorageKeysBeforeJourney,
5508						localStorageKeysAfterJourney,
5509					})}`,
5510				);
5511			// (d) The settings-change — the last journey leg, and last on purpose.
5512			// The project switch below changes the current project, so the leg-(e)
5513			// persistence census above had to be read from the project the rest of the
5514			// journey built BEFORE this leg moves off it: create→c→b→reload→read the
5515			// store→d.
5516			const settingsChange = SUPER_PRODUCTIVITY_JOURNEY.settingsChange;
5517			const readCurrentProjectTitle = async (): Promise<string> => {
5518				const [group] = await lifecycle.groupedText(settingsChange.currentTitleProbe);
5519				const title = group?.name;
5520				if (title === undefined || title.length === 0)
5521					throw new Error('Super Productivity current-project title read empty');
5522				return title;
5523			};
5524			// The ad-hoc two-phase probe leg (d) needs: the contrast custom property on
5525			// the body, read once before the theme control is driven and once after. It is
5526			// disjoint from the fixed end-of-journey style probes taken above.
5527			const themeProbe: readonly WitnessRenderedStyleProbe[] = [
5528				{
5529					label: 'theme-contrast',
5530					selector: settingsChange.theme.styleProbe,
5531					properties: [settingsChange.theme.styleVar],
5532				},
5533			];
5534			const readContrast = async (): Promise<string> => {
5535				const [probe] = await lifecycle.probeStyles(themeProbe);
5536				const value = probe?.properties[settingsChange.theme.styleVar];
5537				if (value === undefined || value.length === 0)
5538					throw new Error('Super Productivity theme contrast custom property read empty');
5539				return value;
5540			};
5541	
5542			// The project-switch spine. One project exists — the default the application
5543			// seeds — and the side-nav addProject() control opens the create dialog. A
5544			// title typed into it and submitted grows the side-nav project list from one to
5545			// two; the count settling at two is the measurement, not a timer.
