5551				settingsChange.projectSwitch.titleInput,
5552				settingsChange.projectSwitch.newProjectTitle,
5553				{ redact: false },
5554			);
5555			await page.click(settingsChange.projectSwitch.submit);
5556			await context.expect.page.count(page, settingsChange.projectSwitch.dialog, 0);
