5564			await context.expect.page.text(
5565				page,
5566				settingsChange.projectSwitch.titleControl,
5567				settingsChange.projectSwitch.newProjectTitle,
5568			);
5569			const currentTitleAfter = await readCurrentProjectTitle();
5570	
5571			// Into the current project's settings through the header control, and the theme
5572			// config-section expanded so its own controls render. The scroll on this route
5573			// is measured like every other stage; the application pins its drawer container
5574			// to the viewport here too, so it records as absence.
5575			await page.click(settingsChange.settingsNav);
5576			await context.expect.page.count(page, settingsChange.theme.autoContrastControl, 1);
