5609			await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.hostTag, 1);
5610			await measure('/#/work-view (after the `w` shortcut)');
5611			const settings: WitnessAngularSuperProductivityJourney['settings'] = {
5612				state: 'measured-settings-change',
5613				projectSwitch: {
5614					control: settingsChange.projectSwitch.addControl,
5615					dialog: settingsChange.projectSwitch.dialog,
5616					titleControl: settingsChange.projectSwitch.titleControl,
5617					switchControl: settingsChange.projectSwitch.switchControl,
5618					newProjectTitle: settingsChange.projectSwitch.newProjectTitle,
5619					currentTitleBefore,
5620					currentTitleAfter,
