5628					styleValueBefore,
5629					styleValueAfter,
5630				},
5631				shortcut: {
5632					key: settingsChange.shortcut.key,
5633					hostTag: settingsChange.shortcut.hostTag,
5634					hostTagPresentAfter: 1,
5635				},
5636			};
5637	
5638			await context.expect.page.outcome(page, {
5639				events: { input: { atLeast: 1 }, keydown: { atLeast: 1 } },
5640			});
5641			await clean(
5642				context,
5643				page,
5644				SUPER_PRODUCTIVITY_JOURNEY.navigations,
5645				lifecycle.expectedConsoleErrors,
5646				lifecycle.expectedFailedRequests,
5647			);
5648			// Anchored on the probe both lanes agree on rather than on the document
5649			// body, whose family list genuinely differs across the lift. The reasoning
5650			// is in the schema beside the constant.
5651			const typefaceProbe = renderedStyles.find(
5652				(probe) => probe.label === WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_PROBE,
5653			);
5654			const resolvedFontFamily = typefaceProbe?.properties['font-family'];
5655			if (resolvedFontFamily === undefined || resolvedFontFamily.length === 0)
5656				throw new Error('Super Productivity typeface probe resolved no font family');
5657			const applicationJourney: WitnessAngularSuperProductivityJourney = {
5658				typeface: {
5659					state: 'measured-typeface-degradation',
5660					cause: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_DEGRADATION_CAUSE,
5661					fontFaceDeclared: resolvedFontFamily.includes(
5662						WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE,
5663					),
5664					resolvedFontFamily,
5665					masked: false,
5666				},
5667				persistence: {
5668					store: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.store,
5669					databaseName: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.databaseName,
5670					storeName: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.storeName,
5671					backend: 'none',
5672					stubbed: false,
5673					driverInUse: SUPER_PRODUCTIVITY_JOURNEY.driverInUse,
5674					keysBeforeJourney,
5675					keysAfterJourney,
5676					localStorageKeysBeforeJourney,
5677					localStorageKeysAfterJourney,
5678					survivesOnlineReload: true,
5679				},
5680				drag: {
5681					state: 'measured-task-list-reorder',
5682					surface: ANGULAR_SUPER_PRODUCTIVITY_APP,
5683					pointer: 'genuine-dragula-pointer-down-move-up',
5684					movedTask: SUPER_PRODUCTIVITY_JOURNEY.reorder.movedTask,
5685					renderedOrderBefore,
5686					renderedOrderAfter,
5687					storeOrderAfter,
5688				},
5689				timeTracking: {
5690					state: 'measured-task-time-tracking',
5691					control: 'main-header .play-btn mat-icon',
5692					iconBeforeStart,
5693					iconAfterStart,
5694					iconAfterStop,
5695					currentTasksOnStart: 1,
5696					currentTasksOnStop: 0,
5697				},
5698				settings,
5699			};
5700			return {
5701				assertions: [
5702					'the work view rendered on the application own declared `#/work-view` route, under its own `work-view` host tag, with two task lists and no task in either',
5703					'a task created through the application own add-task bar by typing a title and committing it with Enter, landing in today list rather than in the backlog',
5704					'the created task rendered in the task list with the typed title read back off the page',
5705					'a second task created the same way, the two rendering first-created on top, which is the order leg (b) reorders from',
5706					'leg (c): the header own global play button flipping its icon from play_arrow to pause on start with one task made current, and back to play_arrow on stop with the current task cleared',
