5708					'the application own IndexedDB store read for its KEYS either side of the journey, adding the four state documents the application writes for its default project and removing none',
5709					'the two tasks surviving a real document reload in the drag-settled order, read back off the re-rendered list — the store agreeing with the drag — with the store census unchanged',
5710					'a real ngsw registered, activated and controlling the page at all three checkpoints, with the worker scripts the build shipped byte-identical either side of the run',
5711					'the linked Roboto stylesheet answered in-context, with the resolved family measured rather than assumed',
5712					'leg (d): a second project created through the application own addProject() dialog, growing the side-nav project list from one to two, and switching to it flipping the header current-project title to the created project',
5713					'leg (d): the project theme own huePrimary mat-select driven to a non-default hue after unchecking isAutoContrast, shifting the measured `--palette-primary-contrast-50` contrast custom property from a dark contrast to a light one — the driven change never the undriveable color input',
5714					'leg (d): the `w` shortcut bringing the work view back from the project settings, its host tag rendered after the press',
5715					'clean page',
5716				],
5717				offlineEvidence: { state: 'not-applicable' },
5718				realServiceWorker: {
5719					script,
5720					shippedWorkerFiles: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER.shippedWorkerFiles,
5721					checkpoints,
5722				},
5723				renderedStyles,
5724				applicationJourney,
5725				scrollAbsence: {
5726					state: 'measured-no-overflowing-document',
5727					viewport: { ...SUPER_PRODUCTIVITY_JOURNEY.viewport },
5728					routes: measuredRoutes,
5729					documentOverflow:
5730						'the application pins its drawer container to the viewport and gives the task lists their own overflow, so no stage of the journey produces a scrollable document',
5731					claimed: false,
5732				},
5733			};
5734		},
5735	};
5736	apps.push(angularSuperProductivitySpec);
