/**
 * A throwaway live-DOM probe for the Super Productivity leg-(d) theme section
 * (u20c2q). It drives the project-switch spine and the settings navigation with
 * raw Playwright against the same bound lane the asserting journey serves, then
 * prints the structure of the theme config-section — the mat-select ids and the
 * label text around each — so the huePrimary control can be pinned to a unique,
 * measured selector rather than a guessed one.
 *
 * Publishes nothing; stdout only.
 */

import { basename, join, resolve } from 'pathe';
import { chromium } from 'playwright';
import { joinURL } from 'ufo';
import { startStaticServer } from '../witness/real-app-run.ts';

const root = resolve(import.meta.dirname, '../../../..');
const chromiumExecutable = join(
	root,
	'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
);
const laneRoots = {
	baseline: join(
		root,
		'.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
	),
	migrated: join(root, '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-25'),
} as const;

async function probe(lane: 'baseline' | 'migrated'): Promise<void> {
	const server = await startStaticServer(laneRoots[lane], { profile: 'current-witness' });
	const browser = await chromium.launch({ executablePath: chromiumExecutable });
	const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
	await context.route('**/*', async (route) => {
		const url = route.request().url();
		if (url.startsWith(server.origin)) return route.continue();
		return route.fulfill({ status: 200, contentType: 'text/css', body: '' });
	});
	const page = await context.newPage();
	const log = (label: string, value: unknown): void =>
		process.stdout.write(`[${lane}] ${label}: ${JSON.stringify(value)}\n`);
	try {
		await page.goto(joinURL(server.origin, '/#/work-view'), { waitUntil: 'networkidle' });
		await page.waitForTimeout(1500);
		// Project-switch spine.
		await page.click('section.projects > button[mat-menu-item]');
		await page.waitForTimeout(500);
		await page.fill('dialog-create-project input:not([type=color])', 'Witness leg-d project');
		await page.click('dialog-create-project button[type=submit]');
		await page.waitForTimeout(800);
		await page.click('side-nav .project:nth-of-type(2) > button[mat-menu-item]');
		await page.waitForTimeout(800);
		await page.click('main-header .project-settings-btn');
		await page.waitForTimeout(1000);
		log('config-section-count', await page.locator('section.config-section').count());
		// Expand the theme section (2nd).
		await page.click('section.config-section:nth-of-type(2) .collapsible-title');
		await page.waitForTimeout(600);
		const theme = 'section.config-section:nth-of-type(2)';
		log('checkbox-count', await page.locator(`${theme} mat-checkbox`).count());
		log('select-count-before-uncheck', await page.locator(`${theme} mat-select`).count());
		// Uncheck isAutoContrast + save.
		await page.click(`${theme} mat-checkbox label`);
		await page.click(`${theme} .submit-button`);
		await page.waitForTimeout(800);
		log('select-count-after-uncheck', await page.locator(`${theme} mat-select`).count());
		// Dump each mat-select's id + the formly-field id/label around it.
		const selects = await page.locator(`${theme} mat-select`).evaluateAll((nodes) =>
			nodes.map((node) => {
				const field = node.closest('formly-field');
				const formGroup = node.closest('mat-form-field');
				const label = formGroup?.querySelector('mat-label')?.textContent?.trim() ?? null;
				return {
					id: (node as HTMLElement).id || null,
					ariaLabel: node.getAttribute('aria-label'),
					fieldTag: field?.tagName?.toLowerCase() ?? null,
					fieldId: (field as HTMLElement | null)?.id || null,
					fieldClass: (field as HTMLElement | null)?.className || null,
					matLabel: label,
				};
			}),
		);
		log('selects', selects);
		// Candidate unique selectors for huePrimary (the first hue select).
		for (const candidate of [
			`${theme} formly-field:has(mat-select):first-of-type mat-select`,
			`${theme} mat-select[id*="huePrimary"]`,
			`${theme} .form-block:nth-of-type(1) mat-select`,
		]) {
			try {
				log(`candidate ${candidate}`, await page.locator(candidate).count());
			} catch (error) {
				log(`candidate ${candidate}`, `ERR ${(error as Error).message.slice(0, 60)}`);
			}
		}
	} catch (error) {
		process.stdout.write(`[${lane}] PROBE ERROR: ${(error as Error).message}\n`);
	} finally {
		await browser.close();
		await server.close();
	}
}

